/**
 * DEV-only custody verification. Never signs, issues, rotates or reads a password.
 * A missing credential mount or either independent public-key pin fails closed.
 * Both attestations must be generated by trusted services OUTSIDE this app.
 */
import { createPublicKey, verify } from "node:crypto";
import { readFile } from "node:fs/promises";

const PROJECT = "xssrfshdrtdfupgqwfdw";
const PRINCIPAL = "openclaw-vps-main";
const SCOPE = "GPT02_READER_CREDENTIAL_CUSTODY_CST_DEV";
const ROLE = "gpt02_owner_ledger_reader_dev";
const MOUNT = "/run/credentials/gpt02-reader-custody";
const MAX_PROOF_BYTES = 4096;
const MAX_PROOF_LIFETIME_MS = 24 * 60 * 60 * 1000;

type Proof = Record<string, unknown>;
type Keys = { worker: string; issuer: string };
type Reader = (path: string) => Promise<string>;

function exactKeys(value: Proof, keys: string[]): boolean {
  return Object.keys(value).sort().join("|") === [...keys].sort().join("|");
}
function asProof(raw: string): Proof | null {
  if (Buffer.byteLength(raw, "utf8") > MAX_PROOF_BYTES) return null;
  try {
    const value: unknown = JSON.parse(raw);
    return value && typeof value === "object" && !Array.isArray(value) ? value as Proof : null;
  } catch { return null; }
}
function pinnedKey(value: string) {
  if (!/^[A-Za-z0-9+/]+={0,2}$/.test(value) || value.length > 1500) return null;
  try {
    const der = Buffer.from(value, "base64");
    if (der.toString("base64") !== value) return null;
    const key = createPublicKey({ key: der, format: "der", type: "spki" });
    return key.type === "public" && key.asymmetricKeyType === "ed25519" ? key : null;
  } catch { return null; }
}
function validTime(issuedAt: unknown, expiresAt: unknown, now: number): boolean {
  return typeof issuedAt === "number" && typeof expiresAt === "number" &&
    Number.isSafeInteger(issuedAt) && Number.isSafeInteger(expiresAt) &&
    issuedAt <= now && now < expiresAt &&
    expiresAt - issuedAt > 0 && expiresAt - issuedAt <= MAX_PROOF_LIFETIME_MS;
}
function validSignature(proof: Proof, fields: string[], key: ReturnType<typeof pinnedKey>): boolean {
  if (!key || !exactKeys(proof, [...fields, "signature"]) ||
      typeof proof.signature !== "string" ||
      !/^[A-Za-z0-9+/]{86}==$/.test(proof.signature)) return false;
  const signature = Buffer.from(proof.signature, "base64");
  if (signature.length !== 64 || signature.toString("base64") !== proof.signature) return false;
  const canonical: Proof = {};
  for (const field of fields) canonical[field] = proof[field];
  try { return verify(null, Buffer.from(JSON.stringify(canonical)), key, signature); }
  catch { return false; }
}

const WORKER_FIELDS = ["kind","serviceId","principal","scope","projectId","issuedAt","expiresAt"];
const RECEIPT_FIELDS = ["kind","receiptId","role","projectId","issuedAt","expiresAt"];

/** Path and pinned public keys are deployment inputs, never agent-supplied. */
export function createGpt02ReaderCustodyVerifiedAdapter(input: {
  keys: Keys;
  read?: Reader;
  now?: () => number;
}) {
  const read = input.read ?? ((path: string) => readFile(path, "utf8"));
  const now = input.now ?? Date.now;
  const workerKey = pinnedKey(input.keys.worker);
  const issuerKey = pinnedKey(input.keys.issuer);
  // A single signer must NEVER be able to issue both worker and DBA proofs.
  const distinctKeys = !!workerKey && !!issuerKey &&
    input.keys.worker !== input.keys.issuer;

  return {
    async verifyWorkerAttestation(serviceId: string, principal: string): Promise<boolean> {
      if (!distinctKeys || !serviceId || principal !== PRINCIPAL) return false;
      try {
        const proof = asProof(await read(MOUNT + "/worker-attestation.json"));
        if (!proof || proof.kind !== "GPT02_DEV_WORKER_ATTESTATION_V1" ||
            proof.serviceId !== serviceId || proof.principal !== PRINCIPAL ||
            proof.scope !== SCOPE || proof.projectId !== PROJECT ||
            !validTime(proof.issuedAt,proof.expiresAt,now())) return false;
        return validSignature(proof,WORKER_FIELDS,workerKey);
      } catch { return false; }
    },
    async readDbaCustodyReceipt(): Promise<{ verified: boolean; receiptId: string | null }> {
      if (!distinctKeys) return { verified:false, receiptId:null };
      try {
        const proof = asProof(await read(MOUNT + "/issuer-receipt.json"));
        if (!proof || proof.kind !== "GPT02_DEV_OWNER_READER_ISSUER_RECEIPT_V1" ||
            proof.role !== ROLE || proof.projectId !== PROJECT ||
            typeof proof.receiptId !== "string" ||
            !/^[a-zA-Z0-9_-]{8,100}$/.test(proof.receiptId) ||
            !validTime(proof.issuedAt,proof.expiresAt,now()) ||
            !validSignature(proof,RECEIPT_FIELDS,issuerKey))
          return { verified:false, receiptId:null };
        return { verified:true, receiptId:proof.receiptId };
      } catch { return { verified:false, receiptId:null }; }
    },
  };
}

export function createConfiguredGpt02ReaderCustodyAdapter() {
  // PROD and any ambiguous deployment remain locked even if pins are present.
  const dev = process.env["APP_ENV"] === "development" &&
    process.env["NODE_ENV"] !== "production";
  return createGpt02ReaderCustodyVerifiedAdapter({
    keys: {
      worker: dev ? process.env["GPT02_DEV_CUSTODY_ATTESTOR_PUBLIC_KEY_SPKI_B64"] ?? "" : "",
      issuer: dev ? process.env["GPT02_DEV_CUSTODY_ISSUER_PUBLIC_KEY_SPKI_B64"] ?? "" : "",
    },
  });
}
